"""Synthetic ground truth for the input-output identification tests and the demo: G9 MotionSegments generated by an
INDEPENDENT integrator (scipy solve_ivp, tight tolerances, per ZOH interval -- not the estimator's hybrid stepper),
camera-rate q with noise, 50 Hz effort rows with their sigma. Every segment is monotonic (one velocity sign)."""
from __future__ import annotations

import numpy as np
from scipy.integrate import solve_ivp


def truth_rollout(t_query, *, M, c, Fc, t0, q0, v0, effort_t=None, effort=None, G=None, kappa=0.0, q_eq=0.0):
    """Dimensional M qdd + c qd + Fc s + G(q) + kappa (q - q_eq) = u (ZOH), sliding sign fixed by v0 (asserted)."""
    s = 1.0 if v0 > 0 else -1.0
    tq = np.asarray(t_query, float)
    if effort_t is None:
        effort_t, effort = np.array([t0]), np.array([0.0])
    knots = sorted(set([t0] + [x for x in effort_t if t0 < x < tq[-1]] + [tq[-1]]))
    y = np.array([q0, v0], float)
    out = np.empty(len(tq))
    for a, b in zip(knots[:-1], knots[1:]):
        k = int(np.searchsorted(effort_t, a, side="right") - 1)
        u = float(effort[max(k, 0)])

        def f(t, x):
            g = G(x[0]) if G else 0.0
            return [x[1], (u - c * x[1] - Fc * s - g - kappa * (x[0] - q_eq)) / M]
        m = (tq >= a) & (tq <= b)
        r = solve_ivp(f, (a, b), y, rtol=1e-11, atol=1e-13, dense_output=True)
        if m.any():
            out[m] = r.sol(tq[m])[0]
        y = r.y[:, -1]
        if np.sign(y[1]) != s:
            raise ValueError("synthetic truth crossed zero velocity (choose a monotonic window)")
    return out


def segment(name, *, label, joint_type="revolute", M=1.0, c=0.5, Fc=0.2, q0=0.0, v0=1.0, T=1.5, cam_hz=30.0,
            q_noise=1e-3, effort_levels=None, effort_hz=50.0, effort_sigma=0.02, G=None, seed=0, t_start=0.0,
            kappa=0.0, q_eq=0.0, effort_override=None):
    """One MotionSegment. ``effort_levels``: callable t -> u (sampled at effort_hz, ZOH) for FORCED segments.
    ``effort_override``: the RECORDED effort differs from the TRUE one (mutation tests: lag / sign / lever)."""
    from ..free_forced.segments import MotionSegment
    rng = np.random.default_rng(seed)
    t = t_start + np.arange(0.0, T, 1.0 / cam_hz)
    ft = Q = Qs = None
    if label == "FORCED_MEASURED":
        ft = t_start - 0.1 + np.arange(0.0, T + 0.2, 1.0 / effort_hz)
        Q = np.array([effort_levels(x) for x in ft], float)
        Qs = np.full_like(Q, effort_sigma)
    qt = truth_rollout(t, M=M, c=c, Fc=Fc, t0=float(t[0]), q0=q0, v0=v0, effort_t=ft, effort=Q, G=G, kappa=kappa,
                       q_eq=q_eq)
    q = qt + rng.normal(0, q_noise, len(t))
    Q_rec = Q
    if label == "FORCED_MEASURED":
        Q_rec = Q + rng.normal(0, effort_sigma, len(Q))
        if effort_override is not None:
            Q_rec = np.array([effort_override(x) for x in ft], float) + rng.normal(0, effort_sigma, len(Q))
    return MotionSegment(name, label, joint_type, t, q, np.full_like(t, q_noise), 1.0 if v0 > 0 else -1.0,
                         ft, Q_rec, Qs, dict(reason="SYNTHETIC", interval_rows=[0, 1], truth=dict(M=M, c=c, Fc=Fc)))


def episodes(segs, force_audit_status="VERIFIED", heldout="none", **kw):
    from .segmentation_adapter import from_segments
    eps, g10, excl, reg = from_segments(segs, force_audit_status=force_audit_status, heldout=heldout, **kw)
    return eps


def pulse_train(levels, period=0.25, duty=0.6, base=0.0):
    """Piecewise-constant pulses (ZOH at the effort rate), cycling through ``levels``."""
    levels = list(levels)

    def u(t):
        k = int(np.floor(max(t, 0.0) / period))
        ph = max(t, 0.0) / period - k
        return float(levels[k % len(levels)] if ph < duty else base)
    return u
